custom_css:
/* === 气象图 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Yomogi&display=swap'); /* 随性日文手写体 */
@import url("https://fontsapi.zeoseven.com/281/main/result.css"); /* 全局中文: Xiaolai */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/438/main/result.css"); /* 引用: Huiwen-ZhengKai */
@import url("https://fontsapi.zeoseven.com/498/main/result.css"); /* 标题: 平方刘昂乐天体 */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg-color: #EAF4FC; /* 雨滴浅蓝 */
    --theme-bg-mid: #B9D8F1; /* 雨后晴空蓝 */
    --card-bg: rgba(255, 255, 255, 0.85); /* 半透明水雾白 (AI默认) */
    --accent-blue: #5C9ACF; /* 深海/雨滴蓝 */
    --accent-green: #7FB5B5; /* 水雾青绿（点缀） */
    --text-main: #2C405A; /* 深灰蓝，阅读舒适 */
    --text-subtle: #6B849C; /* 浅灰蓝 */

    --font-japanese: 'Yomogi', cursive;
    --font-main: "Xiaolai", var(--font-japanese), sans-serif;
    --font-quote: "Huiwen-ZhengKai", var(--font-japanese), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "平方刘昂乐天体", var(--font-japanese), sans-serif;
}

/* --- 3. 全局样式与无阴影无边框设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/0eXL/1200X796/807f5e4af6528b8d3402b186d17c2af4.jpg/webp'); /* 使用天际线作为全局底图 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 全局微雨遮罩层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: repeating-linear-gradient(160deg, rgba(255,255,255,0.05) 0px, rgba(255,255,255,0.05) 1px, transparent 1px, transparent 40px);
    pointer-events: none; z-index: 9999; mix-blend-mode: overlay;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(234, 244, 252, 0.6); backdrop-filter: blur(12px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.4s ease; }
.drawer-icon.fa-fw:hover { transform: translateY(-5px) scale(1.1); }

/* 导航栏贴图替换 (绑定唯一ID，彻底解决不生效问题) */
#ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/4yyn/1597X1325/2026-04-26_150934.png/webp') !important; 
}
#sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #backgrounds-button .drawer-icon, #table_database_settings_drawer .drawer-icon, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/ybC0/1234X1901/2026-04-26_150923.png/webp') !important; 
}

/* 右侧风铃贴纸动效 (拼贴感白边通过drop-shadow实现) */
#top-settings-holder::after {
    content: ''; position: absolute; right: 25px; top: 5px;
    width: 45px; height: 150px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/m3Ev/551X1859/2026-04-26_150832.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: top center;
    pointer-events: none; z-index: 100;
    transform-origin: top center;
    animation: wind-chime-swing 5s ease-in-out infinite alternate;
    filter: drop-shadow(0 0 2px white) drop-shadow(0 0 2px white); 
}
@keyframes wind-chime-swing { 0% { transform: rotate(-8deg); } 100% { transform: rotate(12deg); } }

/* 抽屉与弹窗背景图替换 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(245, 250, 255, 0.8), rgba(245, 250, 255, 0.85)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/0eXL/1200X796/807f5e4af6528b8d3402b186d17c2af4.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 12px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 20px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { 
    pointer-events: auto; width: 85% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: rgba(255, 255, 255, 0.75) !important; padding: 12px 20px !important; 
    backdrop-filter: blur(15px) !important; -webkit-backdrop-filter: blur(15px) !important; 
    border-radius: 30px !important; 
    transition: all 0.5s ease !important; position: relative;
    animation: gentle-wave-float 6s ease-in-out infinite;
}
@keyframes gentle-wave-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }

#rightSendForm, #leftSendForm { gap: 12px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

/* 治愈系输入框伪提示词 (已缩小字号) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'ねぇ、今から晴れるよ... ☂️'; 
    color: var(--accent-blue); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-japanese); font-size: 0.95em; pointer-events: none; z-index: 10; white-space: nowrap; 
    opacity: 0.7; animation: rain-breathe 3s infinite alternate;
    letter-spacing: 2px;
}
@keyframes rain-breathe { 0% { opacity: 0.4; transform: translate(-50%, -48%); } 100% { opacity: 0.8; transform: translate(-50%, -50%); } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 38px; height: 38px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s ease; font-size: 0; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.15) translateY(-3px); }

/* 底栏图标替换 */
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/8bCy/1015X1616/2026-04-26_150809.png/webp') !important; }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/RvOY/1781X1783/2026-04-26_150709.png/webp') !important; }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/rETU/1882X1359/2026-04-26_150742.png/webp') !important; }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/8bCy/1015X1616/2026-04-26_150809.png/webp') !important; filter: hue-rotate(45deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/RvOY/1781X1783/2026-04-26_150709.png/webp') !important; filter: hue-rotate(90deg); }

/* --- 6. 核心：网页窗口式消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 35px 0 0 0 !important; /* 顶部留出空间放置网页UI栏 */
    margin: 80px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    border-radius: 12px !important; 
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    overflow: visible !important;
    position: relative; z-index: 10;
    background-clip: padding-box;
}

/* 【用户专属：浅绿色背景】 */
.mes[is_user="true"] {
    background-color: rgba(232, 248, 240, 0.88) !important; 
}

/* 纯CSS绘制的网页/应用窗口头部 (修复z-index层级，放置在底层) */
.mes::before {
    content: '☁️ 天気記録・System Log';
    position: absolute; top: 0; left: 0; right: 0; height: 35px;
    background: linear-gradient(to right, #D8EAF8, #F0F6FA);
    border-top-left-radius: 12px; border-top-right-radius: 12px;
    display: flex; align-items: center; justify-content: center;
    font-family: var(--font-japanese); font-size: 13px; color: var(--accent-blue);
    letter-spacing: 2px; z-index: 5; /* 降低层级 */
}
/* 左上角的浏览器蓝白圆点 */
.mes::after {
    content: '● ● ●';
    color: #B9D8F1;
    font-size: 12px; letter-spacing: 6px;
    position: absolute; top: 8px; left: 18px;
    z-index: 6; /* 降低层级 */
}

/* 【用户专属：浅绿色渐变头部与绿点】 */
.mes[is_user="true"]::before {
    background: linear-gradient(to right, #CFEAD9, #E6F5EC);
    color: #5C957A;
}
.mes[is_user="true"]::after {
    color: #ACD6BD;
}

/* 消息框顶部独立海报横幅区 (衔接在网页窗口栏下方，层级提升) */
.mes .mesAvatarWrapper {
    display: block; padding: 0; margin-top: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 10; /* 提高层级浮于边框之上 */
    overflow: visible !important;
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/cVwb/3929X2497/%E7%B2%89%E8%93%9D%E8%89%B2%E5%94%AF%E7%BE%8E%E7%88%B1%E6%83%85%E7%94%B5%E5%BD%B1%E5%AE%A3%E4%BC%A0%E6%B5%B7%E6%8A%A5%EF%BC%88%E6%A8%AA%E7%89%88%EF%BC%89_%281%29.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/71fu/4209X2720/%E7%B2%89%E8%93%9D%E8%89%B2%E5%94%AF%E7%BE%8E%E7%88%B1%E6%83%85%E7%94%B5%E5%BD%B1%E5%AE%A3%E4%BC%A0%E6%B5%B7%E6%8A%A5%EF%BC%88%E6%A8%AA%E7%89%88%EF%BC%89_%E5%89%AF%E6%9C%AC_%281%29.png/webp'); }

/* 悬浮头像框 (层级最高，彻底摆脱遮挡) */
.mes .avatar {
    position: absolute;
    top: -45px; 
    width: 90px; height: 90px; 
    background: rgba(255,255,255,0.8) !important; 
    padding: 6px !important; 
    z-index: 20; /* 提高层级 */
    display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
}
.mes[is_user="false"] .avatar { left: 30px; transform: rotate(-3deg); }
.mes[is_user="true"] .avatar { right: 30px; left: auto; transform: rotate(3deg); }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}

/* 消息主体区 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 30px 35px 40px 35px !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; z-index: 10; }
/* 文字强制z-index为2 */
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 2; }

/* 天气之子日文台词水印点缀 */
.mes .mes_block::before {
    content: 'あの日、私たちは世界のかたちを\A 決定的に変えてしまったんだ。';
    white-space: pre;
    position: absolute; right: 25px; bottom: 25px;
    font-family: var(--font-japanese); font-size: 16px;
    color: rgba(92, 154, 207, 0.12);
    writing-mode: vertical-rl;
    z-index: 1; pointer-events: none;
    line-height: 2;
}
.mes[is_user="true"] .mes_block::before {
    content: '祈りだけで晴れを呼べるなんて、\A 嘘みたいだ。';
    left: 25px; right: auto;
    color: rgba(92, 149, 122, 0.15); /* 用户框水印偏绿 */
}

/* 治愈系思维链 (CoT) 自定义 */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "💧 雨音を聴きながら考えている... (Thinking)"; 
    font-family: var(--font-japanese); font-size: 18px !important; 
    color: var(--accent-green); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 18px !important; margin-bottom: 25px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; 
    background: repeating-linear-gradient(180deg, var(--accent-blue), var(--accent-blue) 4px, transparent 4px, transparent 8px);
    opacity: 0.6; border-radius: 2px;
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 15px; text-align: justify; }

/* --- 楼层信息、名字、按钮与时间戳 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

/* 名字平移与样式 */
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -70px !important; 
    left: 0; right: 0; width: 100% !important; 
    align-items: center !important; background: transparent !important; 
    z-index: 100; padding: 0 40px; 
}
.mes[is_user="false"] .ch_name { justify-content: flex-end !important; }
.mes[is_user="true"] .ch_name { justify-content: flex-start !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; }
.mes .ch_name .name_text { font-family: var(--font-japanese); font-size: 24px !important; color: #fff !important; text-shadow: 1px 1px 4px rgba(0,0,0,0.25); letter-spacing: 2px; }

/* 时间戳与楼层ID */
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: var(--text-subtle) !important; font-size: 13px !important; font-family: var(--font-japanese); opacity: 0.8; }
.mesIDDisplay::before { content: '雫の記録・Log '; }
.mesIDDisplay::after { content: ' 🎐'; }

.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0.1; transition: opacity 0.3s ease; pointer-events: auto !important; margin-top: 15px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(234, 244, 252, 0.8) !important; color: var(--accent-blue) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-green) !important; color: #fff !important; transform: scale(1.1) rotate(15deg); }

.mes[is_user="true"] .mes_buttons .mes_button, .mes[is_user="true"] .mes_edit_buttons .mes_button {
    background-color: rgba(207, 234, 217, 0.8) !important; color: #5C957A !important;
}
.mes[is_user="true"] .mes_buttons .mes_button:hover, .mes[is_user="true"] .mes_edit_buttons .mes_button:hover {
    background-color: #5C957A !important; color: #fff !important;
}

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260426/rETU/1882X1359/2026-04-26_150742.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: gentle-wave-float 1.5s infinite ease-in-out; border: none !important; height: 45px !important; width: 45px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.6) !important; border-radius: 8px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-blue) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.7) !important; color: var(--text-main) !important; border-radius: 6px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255,255,255,1) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.6) !important; color: var(--text-subtle) !important; transition: all 0.3s ease; border-radius: 8px !important; }
.menu_button:hover { background-color: var(--accent-blue) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-green) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(245, 250, 255, 0.9); z-index: 0; border-radius: 12px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-green) !important; color: #fff !important; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 60px auto 40px !important; }
    .mes .avatar { width: 70px; height: 70px; top: -35px; }
    .mes .ch_name .name_text { font-size: 20px !important; }
    .mes .mesAvatarWrapper { height: 130px !important; min-height: 130px !important; }
    .mes .mes_block > .ch_name { top: -60px !important; padding: 0 20px; }
    #top-settings-holder::after { width: 35px; height: 110px; right: 10px; } /* 缩小手机端风铃 */
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
